class CoreException(Exception):
    """Main exception for ute admin library. To be further developed."""


class ValidatorException(CoreException):
    """Base exception for other validator exception"""


class EmptyValidatorListError(ValidatorException):
    """Exception raised if multi-validator is created without sub-validators."""


class ValueNotValid(ValidatorException):
    """Exception raised when validate result is False."""


class ConverterException(CoreException):
    """Base exception for converters."""


class ConvertError(ConverterException):
    """Exception raised when it is not possible to convert provided value."""


class AliasError(CoreException):
    """Exception raised if alias doesn't exist."""


class NameIsProtected(CoreException):
    """Exception raised when key is tried to be overridden."""
